// Rock & Rye spatter: a deterministic scatter (LCG, fixed seed) of short streaks and flecks
// running along the script's diagonal, in navy and red-brown.
function ryeStreaks() {
  let seed = 20261116;
  const rnd = () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648;
  let navy = '', brown = '';
  for (let i = 0; i < 70; i++) {
    const x = 56 + rnd() * 88, y = 90 + rnd() * 108, len = 0.6 + rnd() * (i % 3 ? 1.6 : 5);
    const dx = +(len * 0.5).toFixed(2), dy = +(-len * 0.87).toFixed(2);
    const seg = `M${x.toFixed(2)} ${y.toFixed(2)}l${dx} ${dy}`;
    if (i % 2) navy += seg; else brown += seg;
  }
  return `<path d="${brown}" stroke="#7a1a12" stroke-width=".9" stroke-linecap="round" fill="none"/>
<path d="${navy}" stroke="#2e2a48" stroke-width=".7" stroke-linecap="round" fill="none"/>`;
}

