// Original label: white with the light blue square-dot screen, dots growing toward the base.
function ramDots() {
  let rows = '';
  for (let i = 0; i < 57; i++) {
    const y = +(141.2 + i * 1.55).toFixed(2);
    const sz = +(1.08 + 0.32 * i / 56).toFixed(2);
    rows += `<path d="M70 ${y}H130" stroke-width="${sz}" stroke-dasharray="${sz} ${+(1.55 - sz).toFixed(2)}"/>`;
  }
  return `<g stroke="#5cb2d8" fill="none">${rows}</g>`;
}

